insert into public.courses(id,title,subject,grade,description,status) values
('10000000-0000-4000-8000-000000000001','Electricity','Physics','Class 10','Understand current, circuits and the electrical energy that powers everyday life. A complete, prerequisite-led Class 10 course.','published')
on conflict (id) do nothing;

insert into public.concepts(id,course_id,slug,title,summary,order_index,content) values
('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','current','Electric current','Charge flowing through a conductor: I = Q/t.',0,
'{"explanation":"Electric current is the rate at which electric charge crosses a cross-section: I = Q/t. Charge Q is measured in coulombs (C), time t in seconds (s), and current I in amperes (A). One ampere means one coulomb per second. Conventional current flows from the positive terminal to the negative terminal in the external circuit; electrons in a metal drift in the opposite direction. A steady current requires a complete conducting path and a source of potential difference. Charge is conserved: it is not used up by a bulb.","examples":[{"problem":"12 C passes a point in 4 s. What is the current?","solution":"I = Q/t = 12/4 = 3 A."},{"problem":"A current of 0.5 A flows for 2 minutes. How much charge passes?","solution":"Convert 2 min to 120 s. Q = It = 0.5 × 120 = 60 C."}],"misconceptions":["Current is used up by components.","Conventional current flows in the electron drift direction.","Current and charge are the same quantity."],"revision_notes":"I = Q/t; 1 A = 1 C/s. Convert time to seconds. Current is conserved in a steady series path."}'),
('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','potential','Potential difference','Energy transferred per unit charge: V = W/Q.',1,
'{"explanation":"Potential difference between two points is the work done per unit charge to move charge between them: V = W/Q. A volt is one joule per coulomb. A cell maintains a potential difference that can drive current around a closed circuit. Voltage is measured between two points, while current is measured through a branch. Voltage can exist across an open switch even though no current flows. A voltmeter has very high resistance and is connected in parallel across the component.","examples":[{"problem":"A cell transfers 18 J to 3 C of charge. Find its voltage.","solution":"V = W/Q = 18/3 = 6 V."},{"problem":"What does a 12 V supply mean?","solution":"It can transfer 12 J of electrical energy per coulomb of charge passing through it."}],"misconceptions":["Voltage and current are interchangeable.","Voltage is energy rather than energy per charge.","No current means there cannot be voltage."],"revision_notes":"V = W/Q; 1 V = 1 J/C. Connect a voltmeter in parallel."}'),
('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000001','circuits','Electric circuits','Closed paths, switches and correct meter connections.',2,
'{"explanation":"An electric circuit is a complete path containing a source and conducting connections. Closing a switch completes the path; opening it interrupts current. An ammeter measures branch current and is connected in series. Its very low resistance minimizes its effect on current. A voltmeter measures potential difference and is connected in parallel, with high resistance to draw little current. A short circuit is a very low-resistance path across a source and may produce dangerously large current. Ideal wires have negligible resistance; real wires do not.","examples":[{"problem":"Where should an ammeter be placed to measure bulb current?","solution":"In series in the same branch as the bulb, so the same current passes through both."},{"problem":"Why not connect an ammeter directly across a cell?","solution":"Its low resistance would create a near-short circuit and a large current."}],"misconceptions":["An ammeter is connected in parallel.","An open switch still allows steady current.","A voltmeter should be inserted in series."],"revision_notes":"Ammeter: series, low resistance. Voltmeter: parallel, high resistance. A closed path is required for steady current."}'),
('20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001','ohms-law','Ohm’s Law','Relating voltage, current and resistance at constant temperature.',3,
'{"explanation":"For an ohmic conductor at constant temperature and other physical conditions, potential difference is proportional to current: V = IR. The ratio V/I is its resistance R, measured in ohms (Ω). A graph of V on the vertical axis against I on the horizontal axis is a straight line through the origin with slope R. A graph of I against V has slope 1/R. Ohm’s law is not universal; a filament lamp changes temperature and therefore resistance as current rises.","examples":[{"problem":"A 6 Ω resistor is connected to 12 V. Find the current.","solution":"I = V/R = 12/6 = 2 A."},{"problem":"For a fixed 4 Ω resistor, voltage changes from 4 V to 8 V.","solution":"At constant temperature, current increases from 1 A to 2 A; the resistance stays 4 Ω."}],"misconceptions":["Doubling voltage doubles the resistance of an ohmic resistor.","Ohm’s law applies regardless of temperature.","Every V–I graph has resistance as its slope, regardless of axis choice."],"revision_notes":"V = IR at constant temperature. Check graph axes before interpreting slope."}'),
('20000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000001','resistance','Electrical resistance','Opposition to current and the meaning of an ohm.',4,
'{"explanation":"Resistance describes how strongly a component opposes electric current for a given potential difference. R = V/I, so one ohm means a potential difference of one volt produces one ampere. At fixed voltage, increasing resistance decreases current. For an ohmic conductor at constant temperature, resistance is a property of the conductor; the formula R = V/I measures that property, rather than saying that simply changing V independently changes R. Resistance depends on material, length, cross-sectional area and temperature.","examples":[{"problem":"A resistor carries 0.2 A at 5 V. Find R.","solution":"R = V/I = 5/0.2 = 25 Ω."},{"problem":"Two resistors, 2 Ω and 8 Ω, are separately connected across 8 V.","solution":"Their currents are 4 A and 1 A respectively. The larger resistance allows less current at the same voltage."}],"misconceptions":["Higher resistance always means higher current.","Resistance is used up as current flows."],"revision_notes":"R = V/I. Compare currents at the same voltage. Resistance is measured in Ω."}'),
('20000000-0000-4000-8000-000000000006','10000000-0000-4000-8000-000000000001','resistivity','Resistance and resistivity','Material properties and the relationship R = ρL/A.',5,
'{"explanation":"For a uniform conductor, R = ρL/A. Here L is length in metres, A is cross-sectional area in square metres, and ρ (rho) is resistivity in ohm metres (Ω m). Resistivity characterizes the material at a given temperature; it does not depend on the dimensions of a particular wire. Resistance does depend on those dimensions. A low-resistivity material such as copper is useful for connecting wires. Higher-resistivity alloys such as nichrome are useful for heating elements. Resistivity can change with temperature.","examples":[{"problem":"A wire has ρ = 2 × 10⁻⁸ Ω m, L = 2 m and A = 1 × 10⁻⁶ m². Find R.","solution":"R = ρL/A = (2 × 10⁻⁸ × 2)/(1 × 10⁻⁶) = 0.04 Ω."},{"problem":"A copper wire is cut into two equal lengths. Does its resistivity change?","solution":"No, if temperature is unchanged. Each half has half the original resistance, but the same material resistivity."}],"misconceptions":["Resistivity depends on wire length.","Resistance and resistivity have the same units."],"revision_notes":"R = ρL/A. Resistance: Ω. Resistivity: Ω m. Material and temperature determine ρ."}'),
('20000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000001','factors','Factors affecting resistance','Predicting how wire dimensions change resistance.',6,
'{"explanation":"For a uniform wire at fixed material and temperature, R is proportional to length L and inversely proportional to area A. Doubling L doubles R; doubling A halves R. For a circular wire, A = πr², so doubling radius makes area four times as large and resistance one-quarter at the same length. If a wire is stretched with unchanged volume, both length and area change: doubling length halves area, making resistance four times as large. In ordinary metals, increasing temperature generally increases resistance.","examples":[{"problem":"A 10 Ω wire is replaced by one of the same material and length but twice the cross-sectional area.","solution":"R becomes 10/2 = 5 Ω."},{"problem":"A uniform wire is stretched to twice its original length at constant volume and temperature.","solution":"A halves because LA is constant. R′/R = (2L/L) × (A/(A/2)) = 4."}],"misconceptions":["Doubling radius only doubles area.","Stretching a wire changes its length but not its area.","A thicker wire has greater resistance."],"revision_notes":"Compare R′/R = (L′/L)(A/A′) for the same material and temperature. Radius and area are different quantities."}'),
('20000000-0000-4000-8000-000000000008','10000000-0000-4000-8000-000000000001','combinations','Series and parallel combinations','Same current in series; same voltage in parallel.',7,
'{"explanation":"In a series circuit, the same current flows through each resistor, potential differences add, and equivalent resistance is Rs = R1 + R2 + … . In parallel, each branch has the same potential difference, branch currents add, and 1/Rp = 1/R1 + 1/R2 + … . For two parallel resistors, Rp = R1R2/(R1+R2). A parallel combination has equivalent resistance smaller than its smallest branch resistance. Household appliances are connected in parallel so each receives the supply voltage and can operate independently.","examples":[{"problem":"Find equivalent resistance of 3 Ω and 6 Ω in series and in parallel.","solution":"Series: 3 + 6 = 9 Ω. Parallel: (3 × 6)/(3 + 6) = 2 Ω."},{"problem":"A 6 V supply feeds parallel branches of 3 Ω and 6 Ω. Find the currents.","solution":"Each branch has 6 V. Currents are 2 A and 1 A; total current is 3 A."}],"misconceptions":["Current is always equal in parallel branches.","Voltage is always equal across series resistors.","Adding a parallel branch increases equivalent resistance."],"revision_notes":"Series: same I, add R. Parallel: same V, add reciprocal R. Total parallel current is the sum of branch currents."}'),
('20000000-0000-4000-8000-000000000009','10000000-0000-4000-8000-000000000001','heating','Heating effect of electric current','Joule heating and electrical energy: H = I²Rt.',8,
'{"explanation":"Electrical energy is transferred as heat when current flows through a resistor. Joule’s law of heating is H = I²Rt for steady current, resistance and time. H is in joules when I is in amperes, R in ohms and t in seconds. Using V = IR gives H = VIt = V²t/R for an ohmic resistor. The comparison matters: at fixed current, larger resistance gives more heat; at fixed voltage, larger resistance gives less heat. Heating elements use high-resistivity, high-melting-point materials. A fuse melts when excessive current heats it and opens the circuit.","examples":[{"problem":"A 2 A current passes through 5 Ω for 10 s. Find the heat.","solution":"H = I²Rt = 2² × 5 × 10 = 200 J."},{"problem":"Current doubles while resistance and time stay fixed. How does heat change?","solution":"Heat becomes four times as large, because it is proportional to I²."}],"misconceptions":["Doubling current only doubles heat.","Higher resistance always means more heat, even at fixed voltage.","A fuse is connected in parallel with the appliance."],"revision_notes":"H = I²Rt = VIt. State what is held constant. Convert minutes to seconds."}'),
('20000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000001','power','Electric power and energy','Power ratings, energy use and kilowatt-hours.',9,
'{"explanation":"Electric power is the rate of electrical energy transfer: P = W/t = VI. For an ohmic resistor, P = I²R = V²/R. Power is measured in watts (W); one watt is one joule per second. Energy E = Pt. A kilowatt-hour is a unit of energy, not power: 1 kWh = 1000 W × 3600 s = 3.6 × 10⁶ J. An appliance rating specifies its power at its rated voltage. For example, a 100 W, 200 V resistive device has resistance V²/P = 400 Ω under rated operating conditions.","examples":[{"problem":"A 60 W lamp runs for 5 h. How much electrical energy is used?","solution":"E = 0.060 kW × 5 h = 0.30 kWh = 1.08 × 10⁶ J."},{"problem":"A device draws 2 A from 12 V. Find its power.","solution":"P = VI = 12 × 2 = 24 W."}],"misconceptions":["A kilowatt-hour is a unit of power.","Power and total energy are the same.","Rated power stays the same regardless of applied voltage."],"revision_notes":"P = VI; E = Pt. Use kW and hours for kWh. 1 kWh = 3.6 × 10⁶ J."}')
on conflict (id) do nothing;

insert into public.prerequisites(course_id,concept_id,prerequisite_id)
select '10000000-0000-4000-8000-000000000001'::uuid,
  ('20000000-0000-4000-8000-' || lpad(c::text,12,'0'))::uuid,
  ('20000000-0000-4000-8000-' || lpad(p::text,12,'0'))::uuid
from (values (2,1),(3,1),(3,2),(4,2),(4,3),(5,4),(6,5),(7,6),(8,4),(8,5),(9,4),(9,5),(10,8),(10,9)) as dependencies(c,p)
on conflict do nothing;

insert into public.question_bank(concept_id,difficulty,prompt,options,correct_answer,explanation,rubric)
select ('20000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid,difficulty,prompt,'[]'::jsonb,answer,explanation,rubric
from (values
(1,'easy','6 C of charge crosses a wire in 3 s. What is the current?','2 A','I = Q/t = 6/3 = 2 A.','Must interpret current as charge per time and include A.'),
(1,'medium','A current of 0.25 A flows for 2 minutes. How much charge passes?','30 C','t = 120 s. Q = It = 0.25 × 120 = 30 C.','Look for conversion to seconds and Q = It.'),
(1,'hard','A steady current of 0.4 A enters a bulb in a single closed loop. What current leaves it, and is charge used up?','0.4 A; charge is not used up','Charge is conserved. The bulb transfers electrical energy, not charge into nothing.','Distinguish energy transfer from charge consumption.'),
(2,'easy','A source transfers 12 J to 2 C of charge. Find the potential difference.','6 V','V = W/Q = 12/2 = 6 V.','Voltage is energy transferred per unit charge.'),
(2,'medium','How much energy is transferred when 5 C passes through a potential difference of 9 V?','45 J','W = VQ = 9 × 5 = 45 J.','Use voltage as joules per coulomb, not current.'),
(2,'hard','An ideal 6 V battery is connected to an open switch, with no other components. Is the voltage across the switch zero or 6 V?','6 V','The battery maintains a potential difference even though the open path prevents steady current.','No current does not imply no potential difference.'),
(3,'easy','To measure the current through a bulb, should an ammeter be connected in series or parallel with it?','In series','The same current must flow through the meter and bulb.','Explain same branch current and low meter resistance.'),
(3,'medium','How should a voltmeter be connected to measure the potential difference across a resistor?','In parallel across the resistor','A voltmeter compares two terminal potentials; its high resistance minimizes current drawn.','Mention two points or parallel connection; do not say voltmeters have low resistance.'),
(3,'hard','Why is connecting an ammeter directly across an idealized battery unsafe?','Its low resistance creates a near-short circuit with very high current','An ammeter belongs in series. Across a source, its very small resistance allows a large current.','Relate low resistance to high current; a meter does not limit current by design.'),
(4,'easy','A 4 Ω ohmic resistor has 8 V across it. Find the current.','2 A','I = V/R = 8/4 = 2 A.','Apply Ohm’s law with units.'),
(4,'medium','The voltage across an ohmic resistor doubles at constant temperature. What happens to current and resistance?','Current doubles; resistance stays the same','I = V/R, with R constant under the stated conditions.','Do not infer that R doubles merely from R = V/I.'),
(4,'hard','A graph plots current I vertically against voltage V horizontally for an ohmic resistor. Its slope is 0.2 A/V. Find resistance.','5 Ω','The slope is I/V = 1/R, so R = 1/0.2 = 5 Ω.','Read the axis order; slope is conductance in this graph.'),
(5,'easy','A component carries 0.5 A at 6 V. What is its resistance?','12 Ω','R = V/I = 6/0.5 = 12 Ω.','Compute voltage divided by current.'),
(5,'medium','Resistors of 3 Ω and 6 Ω are separately connected across the same 12 V source. Which carries more current?','The 3 Ω resistor: 4 A versus 2 A','At fixed voltage, I = V/R is inversely proportional to resistance.','Explain the fixed-voltage comparison.'),
(5,'hard','An ohmic resistor has 3 V at 0.2 A, then 6 V at 0.4 A at the same temperature. Did its resistance change?','No; it is 15 Ω in both cases','3/0.2 = 15 and 6/0.4 = 15. Voltage and current change proportionally.','Treat V/I as a ratio, not V alone.'),
(6,'easy','What is the SI unit of resistivity?','Ohm metre (Ω m)','From ρ = RA/L, units are Ω × m²/m = Ω m.','Distinguish resistivity from resistance in Ω.'),
(6,'medium','A uniform wire has resistivity 2 × 10⁻⁸ Ω m, length 1 m and area 1 × 10⁻⁶ m². Find its resistance.','0.02 Ω','R = ρL/A = 2 × 10⁻⁸ / 10⁻⁶ = 0.02 Ω.','Use area in square metres and correct powers of ten.'),
(6,'hard','Two copper wires at the same temperature have different lengths and areas. Must their resistivities be equal?','Yes, for the same material at the same temperature','Resistivity is a material property at a specified temperature; dimensions affect resistance, not resistivity.','Distinguish ρ from R and preserve the temperature assumption.'),
(7,'easy','A wire is replaced by one twice as long, with the same material, area and temperature. How does resistance change?','It doubles','R = ρL/A, so at fixed ρ and A, R is proportional to L.','State the fixed conditions.'),
(7,'medium','A circular wire has its radius doubled while length, material and temperature stay fixed. What is its new resistance relative to the old one?','One-quarter','Area πr² becomes four times larger; resistance is inversely proportional to area.','Do not confuse diameter or radius with area.'),
(7,'hard','A wire is stretched to twice its length with volume, material and temperature unchanged. What happens to its resistance?','It becomes four times the original','Constant volume means area halves, so R′/R = 2/(1/2) = 4.','Both increased length and reduced area must be considered.'),
(8,'easy','What is the equivalent resistance of 2 Ω and 3 Ω connected in series?','5 Ω','Series resistances add: Rs = 2 + 3 = 5 Ω.','Identify a single current path.'),
(8,'medium','Find the equivalent resistance of 6 Ω and 3 Ω in parallel.','2 Ω','1/R = 1/6 + 1/3 = 1/2, so R = 2 Ω.','Same voltage across branches; result must be below 3 Ω.'),
(8,'hard','A 12 V source supplies parallel 4 Ω and 6 Ω branches. Find both branch currents and total current.','3 A and 2 A; total 5 A','Each branch has 12 V. I1 = 12/4 = 3 A, I2 = 12/6 = 2 A. Total is 5 A.','Voltage is equal, but branch currents need not be equal.'),
(9,'easy','A 2 A current flows through a 3 Ω resistor for 5 s. How much heat is produced?','60 J','H = I²Rt = 4 × 3 × 5 = 60 J.','Square current and use seconds.'),
(9,'medium','Current through a resistor triples while resistance and time remain constant. How does the heat produced change?','It becomes nine times as large','H is proportional to I² under the stated conditions.','Recognize squared rather than linear dependence.'),
(9,'hard','Two resistors, 2 Ω and 4 Ω, are separately connected to a fixed 4 V supply for 10 s. Which produces more heat?','The 2 Ω resistor: 80 J versus 40 J','At fixed voltage H = V²t/R. Results are 16 × 10/2 = 80 J and 16 × 10/4 = 40 J.','Do not apply the fixed-current comparison to a fixed-voltage situation.'),
(10,'easy','A device draws 3 A from a 12 V source. What is its power?','36 W','P = VI = 12 × 3 = 36 W.','Use watts for power, not joules or kWh.'),
(10,'medium','A 100 W lamp operates for 4 h. How much energy does it use in kWh?','0.4 kWh','100 W = 0.1 kW. E = Pt = 0.1 × 4 = 0.4 kWh.','Convert watts to kilowatts; kWh is energy.'),
(10,'hard','A resistive heater is rated 1000 W at 200 V. Assuming constant resistance, what power does it draw at 100 V?','250 W','R = 200²/1000 = 40 Ω. P = 100²/40 = 250 W. Halving voltage quarters power.','Respect the constant-resistance assumption and use P = V²/R.')
) as bank(n,difficulty,prompt,answer,explanation,rubric)
on conflict (concept_id,prompt) do nothing;
